import {calculate,rooms} from './model.js';
import {initial,advance,vote,phases,scenarios} from './engine.js';
const $=id=>document.getElementById(id), money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n), escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const model=await fetch('/gwd-model.json').then(r=>{if(!r.ok)throw Error('Modelo indisponível');return r.json()});
$('economic-plan').innerHTML=model.scenarios.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');
function economy(){const result=calculate(model,$('economic-plan').value,Number($('sales-level').value)/100);$('sales-label').textContent=$('sales-level').value+'%';
 const metrics=[['CAIXA ESTIMADO / 90 DIAS',result.cash90],['CUSTO FIXO DE CAIXA / MÊS',result.fixed],['RECEITA HIPOTÉTICA / MÊS',result.revenue],['RESULTADO DE CAIXA / MÊS',result.cashResult],['TRABALHO PRÓPRIO + ATIVOS',result.unpaid],['RESULTADO ECONÓMICO / MÊS',result.economicResult]];
 $('economic-metrics').innerHTML=metrics.map(([label,value])=>`<div class="${value<0?'negative':''}"><small>${label}</small><strong>${money(value)}</strong></div>`).join('');
 $('capacity-note').textContent=`Capacidade de coordenação: ${result.hours.toFixed(1)} h necessárias / ${result.capacity} h disponíveis no cenário. ${result.capacityExceeded?'O volume excede a capacidade prevista. Exige mais contratação, automação comprovada ou menor escopo.':'Inclui 40 h de gestão, vendas e suporte partilhado.'}`;
 $('capacity-note').className='notice'+(result.capacityExceeded?' warning':'');
 $('cost-table').innerHTML=model.costCategories.map(c=>`<tr><td>${c.name}</td><td>${money(result.scenario.fixedCash[c.id])}</td><td>${c.driver}</td></tr>`).join('')+`<tr><td>Montagem inicial / uma vez</td><td>${money(result.scenario.setupCash)}</td><td>Configuração e pequenos serviços</td></tr><tr><td>Reserva de giro / uma vez</td><td>${money(result.scenario.workingCapital)}</td><td>Desfasamento entre pagamento e recebimento</td></tr>`;
 $('sales-table').innerHTML=result.lines.map(l=>`<tr><td>${l.name}</td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(l.revenue)}</td><td>${money(l.cost)}</td></tr>`).join('');
 $('economic-detail').textContent=`Ponto de equilíbrio de caixa, mantendo o mix: ${result.breakeven?money(result.breakeven):'indeterminado sem vendas'}/mês. O Atelier inclui 12 meses de Club; esses compradores não são contados como assinantes adicionais. Repetir vendas do Atelier em meses futuros exige novas turmas. Preços B2B e assinatura são hipóteses a validar, não ofertas já contratadas.`;
}economy();$('economic-plan').onchange=economy;$('sales-level').oninput=economy;
function portfolio(wave='all'){$('portfolio-grid').innerHTML=model.portfolio.filter(p=>wave==='all'||p.wave===Number(wave)).map(p=>`<article class="project"><span class="status">ONDA ${p.wave} · ${p.wave===1?'VALIDAÇÃO INICIAL':p.wave===2?'PARCEIRO NECESSÁRIO':'EXPLORAÇÃO'}</span><h3>${p.name}</h3><p>${p.model}</p><details><summary>Estado e critério de avanço</summary><p>${p.status}</p><p><strong>Próxima prova</strong><br>${p.gate}</p></details><div class="funding">Recursos: ${p.wave===1?'partilha do orçamento do piloto':'orçamento próprio após validação'} · Sem captação concluída declarada</div></article>`).join('');}portfolio();
$('portfolio-filters').onclick=e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('[data-wave]').forEach(x=>x.setAttribute('aria-pressed',x===b));portfolio(b.dataset.wave)};
let state=initial();const labels={running:'Missão em preparação',voting:'Decisão humana necessária',blocked:'A política bloqueou o pedido',rejected:'Pedido vetado',done:'Execução simulada concluída'};
function mission(){const phase=state.stage??0;$('mission-flow').innerHTML=phases.map((p,i)=>`<li class="${i<=phase?'active':''}">${typeof p==='string'?p:p.label??p.role??String(p)}</li>`).join('');$('mission-status').textContent=labels[state.status]??state.status;$('mission-detail').textContent=`Campanha sintética · orçamento pedido ${money((scenarios[state.scenario]?.amount??180000)/100)} · limite ${money(2500)}. Cada avanço gera um evento local.`;$('mission-next').disabled=state.status!=='running';$('mission-votes').innerHTML='';
 if(state.status==='voting'){['Presidência humana','Financeiro humano'].forEach((name,i)=>{const d=document.createElement('div');d.innerHTML=`<strong>${name}</strong><br>`;for(const [label,v] of [['Aprovar','yes'],['Vetar','no']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{state=vote(state,i,v);mission()};d.append(b)}$('mission-votes').append(d)})}
 $('mission-log').innerHTML=(state.audit??state.events??[]).map(e=>`<li>${escape(typeof e==='string'?e:JSON.stringify(e))}</li>`).join('');
}mission();$('mission-next').onclick=()=>{state=advance(state);mission();document.dispatchEvent(new CustomEvent('genesis-mission',{detail:state}))};$('mission-reset').onclick=()=>{state=initial($('mission-scenario').value);mission()};$('mission-scenario').onchange=()=>{state=initial($('mission-scenario').value);mission()};
let selected='';const guidance={member:'O AtlasClub reúne aprendizagem, desafios e partilha de projetos. Podes conhecer a formação atual e pedir informação sobre a assinatura. O acesso depende da oferta adquirida.',builder:'Vamos registar a tua área, experiência e disponibilidade. A equipa analisa a candidatura e apresenta escopo, condições e eventual remuneração antes de qualquer trabalho produtivo. Pagar não garante vaga ou emprego.',investor:'Podes conhecer o plano e manifestar interesse numa conversa de avaliação. A estrutura, o instrumento, os direitos e as condições de uma eventual operação serão apresentados antes de qualquer compromisso. Este formulário não aceita investimentos.',client:'Podemos começar por um fluxo limitado de conteúdo, atendimento ou automação. Indica o problema que pretendes resolver. A equipa prepara diagnóstico, escopo e orçamento.'};
$('path-choices').onclick=e=>{const b=e.target.closest('button');if(!b)return;selected=b.dataset.path;document.querySelectorAll('[data-path]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('chat-log').innerHTML=`<p class="bubble">Olá. Que papel gostarias de explorar no ecossistema?</p><p class="bubble reply">${escape(b.textContent)}</p><p class="bubble">${guidance[selected]}</p>`;$('lead-form').hidden=false;$('lead-status').textContent='';$('path-next').innerHTML= selected==='member'?'<a href="https://club.atlashub.si/formacoes/arquitetura-superinteligencia-agentica">Conhecer o Atelier e o acesso incluído ↗</a><a href="https://hotmart.com/pt-br/club/atlashub/community/15352038">Já sou membro · entrar ↗</a>':selected==='investor'?'<a href="/documentacao#participacao">Ler o percurso de investimento →</a>':selected==='builder'?'<a href="https://goworld.digital/entrar">Conhecer a comunidade GWD ↗</a>':'';};
$('lead-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]');button.disabled=true;$('lead-status').textContent='A registar…';const d=new FormData(form);try{const res=await fetch('/api/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:d.get('name'),email:d.get('email'),market:d.get('market'),area:d.get('area'),intent:d.get('intent'),path:selected,consent:d.has('consent'),adult:d.has('adult'),website:d.get('website')})});const json=await res.json();if(!res.ok)throw Error(json.error||'Serviço indisponível');$('lead-status').textContent=`Interesse registado. Referência ${json.reference}. A equipa poderá contactar-te pelo e-mail indicado. Nenhum pagamento foi solicitado.`;form.reset();}catch(err){$('lead-status').textContent=err.message+' Podes contactar contact@atlashub.si.';}finally{button.disabled=false}};
let sceneLoaded=false;const observer=new IntersectionObserver(async entries=>{if(entries.some(e=>e.isIntersecting)&&!sceneLoaded){sceneLoaded=true;try{const {startScene}=await import('./office.js');await startScene(rooms)}catch(e){$('scene-loading').textContent='O 3D não está disponível neste dispositivo. Explora as mesmas salas através dos botões abaixo.';renderFallback()}}},{rootMargin:'250px'});observer.observe($('scene'));
function renderFallback(){if($('room-buttons').childElementCount)return;rooms.forEach(r=>{const b=document.createElement('button');b.textContent=r.name;b.onclick=()=>{$('room-info').innerHTML=`<p class="eyebrow">${r.role}</p><h3>${r.name}</h3><p>${r.agent}</p><p>${r.output}</p><p>${r.gate}</p>`};$('room-buttons').append(b)})}


